SELECT 'core-2026-09-v4','passive-voice','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"passive-voice","title":"Passive voice: focus on the receiver","level":"B1","order":48,"summary":"Change the focus of a clause while keeping its tense and meaning clear.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Change the starting point","Keep the original tense","Continuous and perfect passives","Negatives, questions and modals"],"rules":[{"title":"Change the starting point","explanation":"A passive clause makes the receiver or affected participant the subject. Build it with **be + past participle**. A by phrase can name the agent when that information matters, but it is often omitted when unknown or obvious.","pattern":"The report **was checked** by the editor.","commonMistakes":["An intransitive verb such as arrive normally has no object to turn into a passive subject."],"examples":["Use present simple passive: “The visitor guide **is prepared** every week.”","Use present simple passive: “The old portrait **is restored** every week.”"],"skill":"form"},{"title":"Keep the original tense","explanation":"The form of **be** carries tense and agreement. The past participle stays the same. Present simple passive uses am/is/are; past simple passive uses was/were. Find the new subject’s number before choosing be.","pattern":"The letters **are delivered**. / The letter **was delivered**.","commonMistakes":["A past participle is not a past-tense marker by itself: is delivered is present passive."],"examples":["Use past simple passive: “The visitor guide **was prepared** yesterday.”","Use past simple passive: “The old portrait **was restored** yesterday.”"],"skill":"meaning"},{"title":"Continuous and perfect passives","explanation":"A continuous passive adds being before the participle. A perfect passive adds been after have. Read the chain from left to right: first tense, then aspect, then passive.","pattern":"It **is being repaired**. / It **has been repaired**.","commonMistakes":["Being and been are not interchangeable: continuous uses being; perfect uses been."],"examples":["Use present continuous passive: “The visitor guide is **being prepared** right now.”","Use present continuous passive: “The old portrait is **being restored** right now.”"],"skill":"contrast"},{"title":"Negatives, questions and modals","explanation":"Put not after the first auxiliary and move that auxiliary before the subject in questions. A modal passive uses modal + be + participle. Do not add do to a passive that already contains be.","pattern":"**Was** it repaired? / It **must be repaired**.","commonMistakes":["A passive is a choice of focus, not automatically better or more formal than active voice."],"examples":["Use a modal passive: “The visitor guide must **be prepared** before Friday.”","Use a modal passive: “The old portrait must **be restored** before Friday.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-passives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Change the focus of a clause while keeping its tense and meaning clear.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Change the starting point","explanation":"A passive clause makes the receiver or affected participant the subject. Build it with **be + past participle**. A by phrase can name the agent when that information matters, but it is often omitted when unknown or obvious.","pattern":"The report **was checked** by the editor.","commonMistakes":["An intransitive verb such as arrive normally has no object to turn into a passive subject."],"examples":["Use present simple passive: “The visitor guide **is prepared** every week.”","Use present simple passive: “The old portrait **is restored** every week.”"],"skill":"form","id":"passive-voice-foundation-1","domain":"information","referenceIds":["bc-passives"],"readingVersion":"core-2026-09-v3"},{"title":"Keep the original tense","explanation":"The form of **be** carries tense and agreement. The past participle stays the same. Present simple passive uses am/is/are; past simple passive uses was/were. Find the new subject’s number before choosing be.","pattern":"The letters **are delivered**. / The letter **was delivered**.","commonMistakes":["A past participle is not a past-tense marker by itself: is delivered is present passive."],"examples":["Use past simple passive: “The visitor guide **was prepared** yesterday.”","Use past simple passive: “The old portrait **was restored** yesterday.”"],"skill":"meaning","id":"passive-voice-foundation-2","domain":"information","referenceIds":["bc-passives"],"readingVersion":"core-2026-09-v3"},{"title":"Continuous and perfect passives","explanation":"A continuous passive adds being before the participle. A perfect passive adds been after have. Read the chain from left to right: first tense, then aspect, then passive.","pattern":"It **is being repaired**. / It **has been repaired**.","commonMistakes":["Being and been are not interchangeable: continuous uses being; perfect uses been."],"examples":["Use present continuous passive: “The visitor guide is **being prepared** right now.”","Use present continuous passive: “The old portrait is **being restored** right now.”"],"skill":"contrast","id":"passive-voice-foundation-3","domain":"information","referenceIds":["bc-passives"],"readingVersion":"core-2026-09-v3"},{"title":"Negatives, questions and modals","explanation":"Put not after the first auxiliary and move that auxiliary before the subject in questions. A modal passive uses modal + be + participle. Do not add do to a passive that already contains be.","pattern":"**Was** it repaired? / It **must be repaired**.","commonMistakes":["A passive is a choice of focus, not automatically better or more formal than active voice."],"examples":["Use a modal passive: “The visitor guide must **be prepared** before Friday.”","Use a modal passive: “The old portrait must **be restored** before Friday.”"],"skill":"application","id":"passive-voice-foundation-4","domain":"information","referenceIds":["bc-passives"],"readingVersion":"core-2026-09-v3"},{"domain":"information","id":"passive-agent-and-focus","title":"Choosing active or passive and including the agent","explanation":"Active and passive clauses organise the same participants differently when the verb permits both. Passive is useful when the affected participant is the topic or the agent is unknown, unimportant or already understood. A by-phrase can restore the agent. Passive does not inherently remove responsibility or make writing more professional.","pattern":"The editor checked it. / It **was checked by the editor**.","examples":["**My bicycle was stolen** last night.","**The report was written by Ana**, not by Bo."],"commonMistakes":["Some verbs do not form an ordinary corresponding passive, and some passives are idiomatic. Do not attempt to passivise a verb merely because a noun follows it."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["The report **was checked** by the editor.","The letters **are delivered**. / The letter **was delivered**.","It **is being repaired**. / It **has been repaired**.","**Was** it repaired? / It **must be repaired**."],"readingVersion":"core-2026-09-v4"},"stage":"5 · Complex sentences","prerequisites":["degree-comparison"],"readingReferenceIds":["bc-passives","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='passive-voice'
